def _batch_copy_with_limits(
    self,
    gvas: np.ndarray,
    addrs: np.ndarray,
    sizes: np.ndarray,
    direction: int,
    max_transfer_blocks: int,
    max_transfer_bytes: int,
) -> int:
    if len(gvas) == 0:
        return 0

    max_transfer_addrs = 0
    if max_transfer_blocks > 0:
        max_transfer_addrs = max_transfer_blocks * self.num_addrs_per_block
    if max_transfer_addrs <= 0:
        max_transfer_addrs = len(gvas)

    assert self.m_store.store is not None
    for start in range(0, len(gvas), max_transfer_addrs):
        end = start + max_transfer_addrs
        split_gvas, split_addrs, split_sizes = self._split_transfer_packets(
            gvas[start:end],
            addrs[start:end],
            sizes[start:end],
            max_transfer_bytes,
        )
        res = self.m_store.store.batch_copy(
            split_gvas.tolist(),
            split_addrs.tolist(),
            split_sizes.tolist(),
            direction,
        )
        if res != 0:
            return res
    return 0

def _set_os_thread_name(self) -> None:
    try:
        libc = ctypes.CDLL("libc.so.6")
        # Linux task comm is limited to 15 visible bytes plus NUL.
        libc.prctl(15, self.name[:15].encode(), 0, 0, 0)
    except Exception:
        pass

def run(self):
    """Run the thread to handle KV cache transfer requests."""
    self._set_os_thread_name()
    self.m_store.set_device()
    self.ready_event.set()
    while True:
        try:
            request_data = self.request_queue.get()

def get_block_hashes(
    block_hashes: BlockHashList | list[str],
    group_block_size: int,
    hash_block_size: int,
) -> BlockHashList | list[str]:
    if group_block_size == hash_block_size:
        return block_hashes
    assert group_block_size % hash_block_size == 0, "block_size must be divisible by hash_block_size"
    scale_factor = group_block_size // hash_block_size
    return [
        _rehash_block_hash_group(block_hashes[idx : idx + scale_factor])
        for idx in range(0, len(block_hashes) // scale_factor * scale_factor, scale_factor)
    ]


def _rehash_block_hash_group(block_hashes: Sequence[BlockHash | str]) -> BlockHash:
    hasher = hashlib.sha256()
    hasher.update(_GROUPED_BLOCK_HASH_DOMAIN)
    hasher.update(len(block_hashes).to_bytes(_GROUPED_BLOCK_HASH_LENGTH_PREFIX_BYTES, "big"))
    for block_hash in block_hashes:
        hash_bytes = _block_hash_to_bytes(block_hash)
        hasher.update(len(hash_bytes).to_bytes(_GROUPED_BLOCK_HASH_LENGTH_PREFIX_BYTES, "big"))
        hasher.update(hash_bytes)
    return BlockHash(hasher.digest())


def _block_hash_to_bytes(block_hash: BlockHash | str) -> bytes:
    if isinstance(block_hash, str):
        if len(block_hash) == 64:
            try:
                return bytes.fromhex(block_hash)
            except ValueError:
                return block_hash.encode("utf-8")
        return block_hash.encode("utf-8")
    return bytes(block_hash)


